  function decode_longwave_absorption_inputs(bytes, output) result(status)
    !! Input is the exact big-endian coefficient file; output preserves undeclared stores.
    integer(c_int8_t), intent(in) :: bytes(:)
    type(longwave_absorption_input_record), intent(inout) :: output
    integer(c_int) :: status
    status = 2_c_int
    if (size(bytes) /= 1454208) return
    if (network_word32(bytes, 1) /= 38400_c_int64_t) return
    if (network_word32(bytes, 38405) /= 38400_c_int64_t) return
    if (network_word32(bytes, 38409) /= 38400_c_int64_t) return
    if (network_word32(bytes, 76813) /= 38400_c_int64_t) return
    if (network_word32(bytes, 76817) /= 225280_c_int64_t) return
    if (network_word32(bytes, 302101) /= 225280_c_int64_t) return
    if (network_word32(bytes, 302105) /= 225280_c_int64_t) return
    if (network_word32(bytes, 527389) /= 225280_c_int64_t) return
